package com.bank.pattern;

import java.util.logging.Logger;

// Builds console text patterns for National Bank of India batch reports.
public class PatternService {
    private static final Logger log = Logger.getLogger(PatternService.class.getName());

    // Returns a right-angled triangle: row r has r stars.
    public String rightTriangle(int height) {
        StringBuilder sb = new StringBuilder();
        for (int row = 1; row <= height; row++) {       // outer: pick the row
            for (int col = 1; col <= row; col++) {      // inner: r stars
                sb.append('*');
            }
            sb.append('\n');                            // end of row
        }
        log.fine(() -> "rightTriangle height=" + height + " built");
        return sb.toString();
    }

    // Returns an inverted triangle: row 1 has `height` stars, decreasing.
    public String invertedTriangle(int height) {
        StringBuilder sb = new StringBuilder();
        for (int row = height; row >= 1; row--) {       // outer counts down
            for (int col = 1; col <= row; col++) {
                sb.append('*');
            }
            sb.append('\n');
        }
        return sb.toString();
    }
}
