package com.bank.pattern;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: print Rajesh's activity ramp-up and wind-down visuals.
public class PatternDemo {
    private static final Logger log = Logger.getLogger(PatternDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        PatternService service = new PatternService();

        int days = 5;
        String rampUp = service.rightTriangle(days);
        log.info(() -> "Rajesh 5-day activity ramp-up:\n" + rampUp);

        String windDown = service.invertedTriangle(days);
        log.info(() -> "Rajesh 5-day activity wind-down:\n" + windDown);
    }
}
